    @Test
    fun theCosineIsAnUnfusedFloat32Sum() {
        for ((i, c) in cases32.withIndex()) {
            val a = FloatArray(c.a.size) { Float.fromBits(c.a[it]) }
            val b = FloatArray(c.b.size) { Float.fromBits(c.b[it]) }
            assertEquals(Float.fromBits(c.expected).toDouble(), SmartRanker.cosine(a, b), "case $i")
        }
    }

    @Test
    fun theScoreIsAnUnfusedFloat64Sum() {
        val names = RankerFeatures.NAMES.take(12)
        for ((i, c) in cases64.withIndex()) {
            val w = DoubleArray(c.w.size) { Double.fromBits(c.w[it]) }
            val model = RankerModel(
                name = "t", features = names, mean = DoubleArray(12), sd = DoubleArray(12) { 1.0 }, weights = w,
                runPenalty = 0.0, anchor = RankerModel.Anchor.SEED, audioWeightOverride = 0.0,
            )
            val row = DoubleArray(RankerFeatures.NAMES.size)
            for (k in 0 until 12) row[RankerFeatures.NAMES.indexOf(names[k])] = Double.fromBits(c.z[k])
            assertEquals(Double.fromBits(c.expected), model.score(row), "case $i")
        }
    }
